// A discovered landmark's commissioning status is public; the rival city,
// construction parcel and progress remain private.
export function getScenicWorkStatus(state,item) {
  if (state.intel) return state.scenicRegistry?.[item] || 'open';
  if (state.cities.some(city=>city.buildings.includes(item))) return 'complete';
  return state.cities.some(city=>city.queue?.item===item) ? 'commissioned' : 'open';
}

export function observedScenicWorks(state,landmarks) {
  const known = {};
  for (const city of state.cities) {
    const item=city.queue?.item;
    if (landmarks.has(SCENIC_WORKS[item]?.landmark)) known[item]='commissioned';
    for (const building of city.buildings) {
      if (landmarks.has(SCENIC_WORKS[building]?.landmark)) known[building]='complete';
    }
  }
  return known;
}
